from pathlib import Path
import json,hashlib,subprocess,shlex
R=Path(__file__).resolve().parents[1]
contract={'contract_name':'RIGID_SPHERE_LUBRICATION_REFERENCE_CONTRACT_V0','status':'FROZEN_BEFORE_TESTS','mu_Pa_s':.001,'geometry':'rigid unequal no-slip spheres','radius_convention':'a=diameter/2, independent fixed per particle','gap_convention':'h=|xi-xj|-a-b; n=(xi-xj)/|xi-xj|','units':'SI: sq/sh kg/s, pu kg*m^2/s, arms m; omega rad/s','sign_convention':'force/torque on particles = - derivative of positive half-dissipation','scalar_sources':[{'source':'Jeffrey & Onishi 1984','doi':'10.1017/S0022112084000355','equations':['3.17-3.19','4.15-4.17','5.5-5.6','7.9-7.10']},{'source':'Townsend 2023','doi':'10.1063/5.0175697','equations':['2-4','10-12','16','19','24','26-27','33-34a']},{'source':'Radhakrishnan 2017','doi':'10.5281/zenodo.1137305','equations':'Forces_Torques.tex section 6 A/B/C functions; section 4 compares Ball-Melrose and incorrect lubricate/poly coupling'}],'Ball_Melrose':{'doi':'10.1016/S0378-4371(97)00412-3','access':'author repository abstract and frozen upstream displayed dissipation; publisher full text HTTP403, repository states full output unavailable','not_claimed':'Full original paper was not accessible/read'},'normal_mode':'JO XA singular 1/xi and log plus xi log terms, excludes O(1) far-field constants','shear_mode':'JO YA log plus xi log terms; same scalar as stable','pump_mode':'Schur complement C11-B11^2/YA_leading of independent transverse matrix; correct unequal-sphere coupled block','translation_rotation':'li=r*Bi/(Bi+Bj); lj=r*Bj/(Bi+Bj); Bi=abs(YB11), Bj=abs(YB21)','finite_gap_completion':'Project-defined frame-invariant near-field completion. Actual r torque arms; pu multiplied (r/(a+b))^2. Retains stable positive sq/sh scalars. Agrees with published singular transverse block at h->0; not full finite-separation Stokes resistance. No fitting. Exact zero pair force/torque on rigid collective motion.','twist_mode':'PENDING_BLOCKER: upstream absent; nonsingular XC contains collective drag and far-field constants; unique relative-mode matching to retained isolated Stokes drag not validated','background':'q0=[Uinf,Omega_inf]; bpair=Rpair*q0-Bslip.T*D*(a+b)*Ebar*n; Ebar=(Ei+Ej)/2. Same leading strain convention as stable, explicit local-affine closure for arbitrary frozen field.','regularization':{'h_min_over_effective_radius':.001,'purpose':'numerical finite resistance before independent hard contact; not measured roughness or elastic shell','cutoff_h_over_effective_radius':.2,'cutoff':'sharp, identical before all convergence candidates'},'gates':{'coeff_relative':1e-10,'coeff_abs_kg_s':1e-25,'coeff_abs_kg_m2_s':1e-37,'pair_force_normalized':1e-12,'torque_balance_normalized':1e-12,'negative_dissipation_scaled_tolerance':1e-12,'gradient_abs_s_inverse':1e-10,'matrix_relative':1e-10,'matrix_symmetry_relative':1e-12,'scaled_min_eigenvalue':-1e-12,'linear_relative_residual':1e-10,'solution_scaled_relative':1e-9,'accepted_gap_min_m':-1e-12,'swept_gap_min_m':-1e-12,'mpi_position_m':1e-10,'mpi_velocity_m_s':1e-10,'mpi_omega_rad_s':1e-7,'permutation_position_m':1e-11,'permutation_velocity_m_s':1e-10,'permutation_omega_rad_s':1e-7,'trajectory_reference_max_m':1e-9,'velocity_reference_max_m_s':1e-9,'omega_reference_max_rad_s':1e-6,'Cgap_trajectory_max_m':1e-8,'Cgap_gap_max_m':1e-8},'C_adv':.25,'C_gap_candidates':[.4,.2,.1],'C_gap_reference':.1,'C_gap_rule':'dt <= Cgap*max(h,h_min)/max(abs(relative normal speed),1e-30), additionally Cadv and physical end time; hard constraints applied to RK2 midpoint and full displacement relative to step-start normal','audit_pair_states':100000,'audit_combined_states':10000,'seed':20260916,'matrix_system_N':[2,3,5,10],'linear_solver':'SELECT_ONLY_AFTER_MATRIX_AUDIT','wall_safety_surface_gap_m':3*1.9989918081065344e-7,'no_inertia':True,'GPU_PERFORMANCE_READY':'NO'}
p=R/'contracts/RIGID_SPHERE_LUBRICATION_REFERENCE_CONTRACT.json'
if p.exists():assert json.loads(p.read_text())==contract
else:p.write_text(json.dumps(contract,indent=2)+'\n')
head='#include <cmath>\nusing std::pow;using std::log;constexpr double MY_PI=3.141592653589793238462643383279502884;\n'
extract=[]
for name,up in [('poly',False),('upoly',True)]:
 file=R/'provenance'/('pair_lubricateU_poly.cpp' if up else 'pair_lubricate_poly.cpp');text=file.read_text();start=text.index('        if (flaglog) {',text.index('double a_pu') if up else 0);end=text.index('} else',start);end=text.index(';',end)+1
 block=text[start:end];(R/'provenance'/('stable_'+name+'_coefficient_literal.txt')).write_text(block+'\n')
 head+='void '+name+'(double radi,double radj,double gap,double*out){double mu=.001,h_sep=gap/radi,beta0=radj/radi,beta1=1+beta0,a_sq=0,a_sh=0,a_pu=0;int flaglog=1;double beta[2][5]={{0},{0}},pre[2];beta[0][1]=beta0;beta[1][1]=beta1;pre[1]=8.0*(pre[0]=MY_PI*mu*radi)*radi*radi;pre[0]*=6.0;\n'+block+'\nout[0]=a_sq;out[1]=a_sh;out[2]=a_pu;}\n'
 extract.append({'file':str(file.relative_to(R)),'sha256':hashlib.sha256(file.read_bytes()).hexdigest(),'line':text[:start].count('\n')+1,'snippet_sha256':hashlib.sha256(block.encode()).hexdigest()})
head+='extern "C" void stable_coefficients(int n,const double*in,double*out){for(int i=0;i<n;i++){poly(in[3*i],in[3*i+1],in[3*i+2],out+6*i);upoly(in[3*i],in[3*i+1],in[3*i+2],out+6*i+3);}}\n'
(R/'src/stable_source_probe.cpp').write_text(head);(R/'provenance/STABLE_COEFFICIENT_EXTRACTION.json').write_text(json.dumps(extract,indent=2)+'\n')
(R/'build_math').mkdir(exist_ok=True)
flags=shlex.split(subprocess.check_output(['pkg-config','--cflags','--libs','hdf5'],text=True))
cmd=['g++','-std=c++17','-O2','-fPIC','-shared','src/rigid_math.cpp','src/frozen_flow.cpp','src/stable_source_probe.cpp','-o','build_math/librigid_math.so',*flags]
p=subprocess.run(cmd,cwd=R,capture_output=True,text=True);(R/'logs/MATH_BUILD.log').write_text(p.stdout+p.stderr);print('BUILD_RC',p.returncode);print(p.stderr[-1800:]);p.check_returncode()
